/// Divides xs[i] by ys[i] (truncating); fails at the first zero divisor.
pub fn divide_all(xs: List[Int], ys: List[Int]) -> Result[List[Int], Str] {
  var out: List[Int] = []
  for i in range(0, xs.len()) {
    let x = xs.get_or(i, 0)
    let y = ys.get_or(i, 0)
    if y == 0 {
      return Err("division by zero at index {i}")
    }
    out = out.push(x / y)
  }
  return Ok(out)
}
